// ============================================
// 4. RELATED PRODUCTS COMPONENT
// ============================================
window.relatedProductsData = function () {
    return {
        relatedProducts: [],
        isLoadingRelated: true,
        
        async init() {
            var meta = window._lastResolvedMeta;
            if (!meta || !meta.category) { 
                this.isLoadingRelated = false; 
                return; 
            }
            
            var currentSlug = meta.slug || meta.id || '';
            try {
                var entries = await window.fetchProducts();
                var related = [];
                
                for (var i = 0; i < entries.length; i++) {
                    var p = entries[i];
                    if ((p.slug === currentSlug || p.id === currentSlug) || p.category !== meta.category) continue;
                    related.push({ 
                        id: p.id, 
                        name: p.name, 
                        slug: p.slug, 
                        price: p.price, 
                        category: p.category, 
                        image: p.image, 
                        publishedat: p.publishedat 
                    });
                }
                this.relatedProducts = related.slice(0, 4);
            } catch (e) {
                console.warn('Related fetch failed:', e);
            } finally {
                this.isLoadingRelated = false;
            }
        },
        
        formatPrice: window.formatPrice
    };
};

// ============================================
// 5. PAYMENT COMPONENT
// ============================================
window.ecommercePayment = function () {
    return {
        step: 1,
        form: {
            name: '',
            email: '',
            phone: '',
            address: '',
            city: '',
            postalCode: '',
            notes: '',
            paymentMethod: 'transfer'
        },
        shippingCost: 0,
        
        nextStep() {
            if (this.step === 1 && this.$store.cart.items.length === 0) return;
            if (this.step === 2 && !this.validateShippingForm()) return;
            if (this.step < 4) this.step++;
        },
        
        prevStep() {
            if (this.step > 1) this.step--;
        },
        
        validateShippingForm() {
            return !!(
                this.form.name &&
                this.form.email &&
                this.form.phone &&
                this.form.address &&
                this.form.city
            );
        },
        
        submitOrder() {
            // Simulasi submit order
            alert('Pesanan dikirim! Nomor pesanan: INV-' + Date.now().toString().slice(-6));
            this.$store.cart.clear();
            this.step = 4;
        },
        
        get grandTotal() {
            return this.$store.cart.total + this.shippingCost;
        }
    };
};